sys_ui_action.script:
function resetAllFields() {

    /*
    MSSCUSTODY-5785 - Revert Fucntionality Single Task
    1) UI Action: Reset All Fields
    2) Script Include  - evalAmendEligibility - Configuration Story : x_hsb11_mss_c_proc.MSSCustodyAmendUtils - evalAmendEligibility
	3) Script Include : x_hsb11_mss_c_proc.MSSCustodyAmendUtils - Method - amendResetAllButtonVisibility
    */

    //Clearing the intial messages available on task
    g_form.clearMessages();
    //Clearing the intial messages available on task
    var charRegex = /[^a-zA-Z0-9\s]/g;
    var slashRegex = /\s/g; //MSSCUSTODY-7158
    var removespecialCharsInbetween = /^[\/\-?:():.+\s']+|[\/\-?:():.+\s']+$|^\s+|\s+$/g;



    function regexonChangeCheck(inputValue) {
        var finalResult = inputValue.replace(charRegex, '');
        finalResult = finalResult.trim();
        finalResult = finalResult.replace(/\s/g, '');
        return finalResult;

    }


    var taskOutcome = g_form.getValue('outcome').toString();

    if ((taskOutcome == '') || (taskOutcome == null) || (taskOutcome == undefined)) {
        g_form.addInfoMessage('Please select a valid outcome to reset fields');
        return false;
    }

    //validating if the outcome is amend to execute
    var eligbleCheck = new GlideAjax('x_hsb11_mss_c_proc.MSSCustodyAmendUtils');
    eligbleCheck.addParam('sysparm_name', 'evalAmendEligibility');
    eligbleCheck.addParam('sysparm_recOutcome', g_form.getValue('outcome'));
    eligbleCheck.addParam('sysparm_recSysID', g_form.getUniqueValue());
    eligbleCheck.addParam('sysparm_tableName', 'x_hsb11_mss_c_proc_mss_custody_task');
    eligbleCheck.getXMLAnswer(handleEligiblity);
    //validating if the outcome is amend to execute

    function handleEligiblity(check) {
        if (check.toString() == 'true') {

            var gm = new GlideModal("glide_confirm_basic", true, 600);
            gm.setTitle("Field Reset Confirmation");
            gm.setPreference("title", "This action will reset the trade amendment fields. Continue?");
            gm.setPreference("onPromptComplete", function() {

                //intimating the user about the progress
                g_form.addInfoMessage('Please wait...');
                //intimating the user about the progress

                //execute the revert functionality
                var resetValues = new GlideAjax('x_hsb11_mss_c_proc.MSSCustodyAmendUtils');
                resetValues.addParam('sysparm_name', 'amendResetTradeDetails');
                resetValues.addParam('sysparm_tradeID', g_form.getValue('trade_id'));
                resetValues.addParam('sysparm_tableName', 'x_hsb11_mss_c_proc_mss_custody_task');
                resetValues.getXMLAnswer(revertFieldValues);
                //execute the revert functionality

            });
            gm.setPreference("onPromptCancel", function() {
                //Clearing the messages if there are any previous when user opts to cancel
                g_form.clearMessages();
                //Clearing the messages if there are any previous when user opts to cancel

            });
            gm.render();

        } else {
            g_form.addInfoMessage('This is only applicable for Trade Amendment');
        }
    }



    function revertFieldValues(tradeDetails) {

        var tradeDataArray = [];
        var tradeData = JSON.parse(tradeDetails);


        //handling special Characters
        var cusRef = tradeData.cusRef;
        if ((cusRef != null) && (cusRef != '') && (cusRef != undefined)) {
            cusRef = cusRef.replace(removespecialCharsInbetween, '');
            cusRef = cusRef.trim(); //MSSCUSTODY-7757

        }
        var susAccNum = tradeData.susAccNum;
        if ((susAccNum != null) && (susAccNum != '') && (susAccNum != undefined)) {
            susAccNum = regexonChangeCheck(susAccNum);

        }
        var accOfClient = tradeData.accOfClient;
        if ((accOfClient != null) && (accOfClient != '') && (accOfClient != undefined)) {
            accOfClient = accOfClient.replace(removespecialCharsInbetween, '');
            accOfClient = accOfClient.trim(); //MSSCUSTODY-7757

        }
        var delivererCusBic = tradeData.delivererCusBic;
        if ((delivererCusBic != null) && (delivererCusBic != '') && (delivererCusBic != undefined)) {
            delivererCusBic = delivererCusBic.replace(slashRegex, ""); //MSSCUSTODY-7158
            var tradeReceiverBic = delivererCusBic.split('/')[0];
            var tradeDeliverCustodianBic = delivererCusBic.split('/')[1];

        }
        var placeofSett = tradeData.placeofSett;
        if ((placeofSett != null) && (placeofSett != '') && (placeofSett != undefined)) {
            placeofSett = regexonChangeCheck(placeofSett);

        }
        var sellBuyBic = tradeData.sellBuyBic;
        if ((sellBuyBic != null) && (sellBuyBic != '') && (sellBuyBic != undefined)) {
            sellBuyBic = sellBuyBic.replace(slashRegex, ""); //MSSCUSTODY-7158
            var tradeBuyerBic = sellBuyBic.split('/')[0];
            var tradeSellerBic = sellBuyBic.split('/')[1];

        }
        var settlementAccNumber = tradeData.counterSettAccNum;
        if ((settlementAccNumber != null) && (settlementAccNumber != '') && (settlementAccNumber != undefined)) {
            settlementAccNumber = regexonChangeCheck(settlementAccNumber);

        }
        //handling special Characters


        tradeDataArray.push(tradeData.securityID, tradeData.tradeDate, tradeData.settlementDate, tradeData.dealPrice, tradeData.dealCurrency, tradeData.settlementCurrency, tradeData.settlementAmount, tradeData.counterPartyRef, cusRef, tradeData.locCode, tradeData.hmiIndicator, tradeData.scripholIndicator, tradeData.cashHoldIndicator, tradeData.gdiIncidcator, tradeData.payMethod, tradeData.switchIndicator, tradeData.switchAcc, tradeData.counterParCode, tradeReceiverBic, tradeDeliverCustodianBic, tradeBuyerBic, tradeSellerBic, placeofSett, susAccNum, settlementAccNumber, tradeData.converAccSwitch, accOfClient, tradeData.amendChargesType, tradeData.amendChargesCCY, tradeData.amendChargesAmt, tradeData.amendNSSC, tradeData.amendSiPurposeCode, tradeData.amendDataSourceScheme, tradeData.amendProprietyCode, tradeData.amendInsIss, tradeData.amendFa);

        var values = ['bulk_id.security_id_sec_id', 'bulk_id.amend_trade_date', 'bulk_id.settlement_date', 'bulk_id.amend_deal_price', 'bulk_id.amend_deal_currency', 'bulk_id.amend_settlement_currency', 'bulk_id.amend_settlement_amount', 'bulk_id.counterparty_reference', 'bulk_id.customer_reference', 'bulk_id.amend_location_code', 'bulk_id.amend_hmi_indicator', 'bulk_id.amend_script_hold_indicator', 'bulk_id.amend_cash_hold_indicator', 'bulk_id.amend_gdi_indicator', 'bulk_id.amend_payment_method', 'bulk_id.amend_switch_indicator', 'bulk_id.amend_switch_account', 'bulk_id.amend_counterparty_code', 'bulk_id.amend_receiver_custodian_bic', 'bulk_id.amend_deliverer_custodian_bic_receiver_custodian_bic', 'bulk_id.amend_buyer_bic', 'bulk_id.amend_seller_bic_buyer_bic', 'bulk_id.amend_place_of_settlement_bic', 'bulk_id.amend_suspense_account_number', 'bulk_id.amend_counterparty_settlement_account_number', 'bulk_id.amend_convert_to_account_switching', 'bulk_id.amend_a_c_of_client', 'bulk_id.amend_charges_type', 'bulk_id.amend_charges_ccy', 'bulk_id.amend_charges_amt', 'bulk_id.amend_nssc', 'bulk_id.amend_si_purpose_code', 'bulk_id.amend_data_source_scheme', 'bulk_id.amend_propriaty_code', 'bulk_id.amend_iss', 'bulk_id.amend_fa'];

        for (var j = 0; j < values.length; j++) {
            g_form.setValue(values[j], tradeDataArray[j]);
        }

        //resetting the remote table fields - duplicate fields
        g_form.setValue("bulk_id.amend_security_id_sec_id_ref", "");
        g_form.setValue("bulk_id.amend_switch_account_ref", "");
        g_form.setValue("bulk_id.amend_counterparty_code_ref", "");
        //resetting the remote table fields - duplicate fields

        //clearing the process completion message
        g_form.clearMessages();
        //clearing the process completion message

        //Intimating the process completion to the user
        g_form.addInfoMessage('Values have been reverted successfully to their previous state');
        //Intimating the process completion to the user

    }


}
